package com.projectdark.mobile;import com.projectdark.mobile.world.*;import java.util.*;
/** User-confirmed identities, video sense fields and separate adapted placement. */
public final class RucesionCoastMonsters {
 public static final List<String> ALL=Collections.unmodifiableList(Arrays.asList("LYK_BLUE_HACON","LYK_RED_HACON","LYK_ARKPUS","LYK_PLANT_ARKPUS","LYK_KAKAPO","LYK_POISON_KAKAPO","LYK_KOATL","LYK_ELECT_KOATL","LYK_TYRANT","LYK_ARIEL"));
 private static final String[] NAMES={"블루하콘","레드하콘","아크퍼스","플렌트아크퍼스","카카포","포이즌카카포","코아틀","일렉코아틀","해안의폭군","아리엘"};
 public static String name(String id){int i=ALL.indexOf(PoteForestMonsterShowcase.species(id));return i<0?null:NAMES[i];}
 public static Integer observedLevel(String id){switch(PoteForestMonsterShowcase.species(id)){case "LYK_BLUE_HACON":return 82;case "LYK_KOATL":case "LYK_ELECT_KOATL":case "LYK_TYRANT":return 98;case "LYK_ARIEL":return 99;default:return null;}}
 public static List<String> roster(String map){switch(RucesionCoastGeometry.index(map)){case 1:return ALL.subList(0,5);case 2:return Arrays.asList("LYK_BLUE_HACON","LYK_RED_HACON","LYK_PLANT_ARKPUS","LYK_KAKAPO","LYK_POISON_KAKAPO");case 3:return ALL.subList(4,9);case 4:return Arrays.asList("LYK_ARIEL","LYK_BLUE_HACON");default:return Collections.emptyList();}}
 public static List<RuntimeState.Monster> spawn(String map){List<RuntimeState.Monster> out=new ArrayList<>();List<String> family=roster(map);if(family.isEmpty())return out;PoteCampaignMapDef d=PoteCampaignMapDef.forId(map);List<WorldMoveTargetController.TileCenter> clear=new ArrayList<>();for(WorldMoveTargetController.TileCenter t:CampaignWorld.connectedTiles(map)){if(Math.hypot(t.x-d.entryX,t.y-d.entryY)<280||Math.hypot(t.x-d.backX,t.y-d.backY)<260||Math.hypot(t.x-d.nextX,t.y-d.nextY)<180)continue;boolean open=true;for(WorldMoveTargetController.Direction step:WorldMoveTargetController.Direction.values())if(d.exactCenter(t.x+step.dx,t.y+step.dy)==null){open=false;break;}if(open)clear.add(t);}
  int z=RucesionCoastGeometry.index(map),count=z==4?9:z==1?72:96;Random rng=new Random(157000L+z);for(int i=0;i<count;i++){String id=z==4?(i==0?"LYK_ARIEL":"LYK_BLUE_HACON"):family.get(i%family.size());float x=z==4&&i==0?d.maxX*.5f:560+rng.nextFloat()*(d.maxX-900),y=z==4&&i==0?d.maxY*.48f:280+rng.nextFloat()*(RucesionCoastGeometry.shoreY(map,x)-460),best=Float.MAX_VALUE;WorldMoveTargetController.TileCenter at=null;
   for(WorldMoveTargetController.TileCenter t:clear){boolean near=false;for(RuntimeState.Monster m:out)if(Math.hypot(t.x-m.x,t.y-m.y)<(m.id.startsWith("LYK_ARIEL")||id.equals("LYK_ARIEL")?240:100)){near=true;break;}if(near)continue;float q=(t.x-x)*(t.x-x)+(t.y-y)*(t.y-y);if(q<best){best=q;at=t;}}
   if(at==null)throw new IllegalStateException("Rucesion clear spawn "+map+" "+i);AbelCombatProfile p=RucesionCombatProfiles.forId(id);RuntimeState.Monster m=new RuntimeState.Monster(id+"#"+i,name(id),at.x,at.y,p.hp,"USER_VIDEO_IDENTITY/ADAPTED_GAMEPLAY");m.level=p.level;m.mp=p.mp;m.maxMp=p.mp;m.campaignRewardProfileId=id;m.respawnSeconds=id.equals("LYK_ARIEL")?Float.POSITIVE_INFINITY:id.equals("LYK_TYRANT")?45:8+i%3;out.add(m);
  }return out;
 }private RucesionCoastMonsters(){}
}
